/**
 * 现代化 API 服务
 * 统一的 HTTP 客户端和请求管理
 */

import axios from 'axios'
import { AGENT_ERROR_MESSAGES } from '@/modules/asset/utils/agentErrors'
import { extractAgentRouteMismatchMessage } from '@/modules/asset/utils/agentRouteMismatch'
import { authService } from '@/core/auth'
import { LOGIN_REDIRECT_URL } from '@/config/route-paths'

// API 配置
const API_CONFIG = {
  baseURL: import.meta.env.VITE_API_BASE_URL || '/sjxy-console',
  timeout: parseInt(import.meta.env.VITE_API_TIMEOUT) || 60000,
  retryAttempts: 3,
  retryDelay: 1000
}

class ApiService {
  constructor() {
    this.client = this.createAxiosInstance()
    this.setupInterceptors()
  }

  /**
   * 创建 Axios 实例
   */
  createAxiosInstance() {
    const instance = axios.create({
      baseURL: API_CONFIG.baseURL,
      timeout: API_CONFIG.timeout,
      headers: {
        'Content-Type': 'application/json',
        'X-Requested-With': 'XMLHttpRequest'
      }
    })

    return instance
  }

  /**
   * 设置拦截器
   */
  setupInterceptors() {
    // 请求拦截器
    this.client.interceptors.request.use(
      config => {
        // 添加认证头
        const authHeaders = authService.getAuthHeaders()
        config.headers = { ...authHeaders, ...config.headers }

        // 如果是 FormData 上传，移除默认的 Content-Type，让浏览器自动设置带 boundary 的 multipart/form-data
        try {
          if (config.data instanceof FormData) {
            if (config.headers && 'Content-Type' in config.headers) {
              delete config.headers['Content-Type']
            }
          }
        } catch {}

        // 添加缓存破坏参数（后端约定使用 cacheBuster）
        if (config.method === 'get' && config.cache !== false) {
          const hasCacheBusterInUrl = config.url && /[?&]cacheBuster=/i.test(config.url)
          const hasCacheBusterInParams = config.params && config.params.cacheBuster !== undefined
          if (!hasCacheBusterInUrl && !hasCacheBusterInParams) {
            config.params = {
              ...config.params,
              cacheBuster: Date.now()
            }
          }
        }

        // 记录请求

        return config
      },
      error => {
        console.error('❌ Request Error:', error)
        return Promise.reject(error)
      }
    )

    // 响应拦截器
    this.client.interceptors.response.use(
      response => {
        return response
      },
      async error => {
        const { config, response } = error

        console.error(`❌ API Error: ${config?.method?.toUpperCase()} ${config?.url}`, {
          status: response?.status,
          message: error.message
        })

        // 捕获并解析 Agent 专属业务错误与 401（仅针对端点级通信接口 /agent/api/agent，避免管理接口 401 被误判为端点鉴权）
        const data = response?.data
        const isAgentEndpointRequest = config?.url && /\/agent\/api\/agent(\/|$|\?)/.test(config.url)
        const isAgentManagementRequest = config?.url && /\/cmdb\/api\/cmdb\/agent(\/|$|\?)/.test(config.url)
        const errCode = data?.errorCode || data?.code
        const agentErrorMap = AGENT_ERROR_MESSAGES
        const routeMessage = extractAgentRouteMismatchMessage(data)
        if (routeMessage) {
          error.message = routeMessage
          return Promise.reject(error)
        }
        if (isAgentEndpointRequest) {
          if (errCode && agentErrorMap[errCode]) {
            error.message = `${agentErrorMap[errCode]} (${data.message || errCode})`
            return Promise.reject(error)
          }
          if (response?.status === 401) {
            error.message = data?.message || data?.error || 'Agent 接口认证失败 (401)'
            return Promise.reject(error)
          }
        } else if (errCode && agentErrorMap[errCode]) {
          error.message = `${agentErrorMap[errCode]} (${data.message || errCode})`
          return Promise.reject(error)
        } else if (
          isAgentManagementRequest &&
          ![401, 403].includes(response?.status) &&
          (data?.message || data?.detail || data?.error)
        ) {
          error.message = data.message || data.detail || data.error
          return Promise.reject(error)
        }

        // 处理认证错误
        if (response?.status === 401) {
          await authService.logout()
          window.location.href = LOGIN_REDIRECT_URL
          return Promise.reject(new Error('Authentication expired'))
        }

        // 处理权限错误
        if (response?.status === 403) {
          return Promise.reject(new Error('Access denied'))
        }

        // 重试逻辑
        if (this.shouldRetry(error)) {
          return this.retryRequest(config)
        }

        return Promise.reject(error)
      }
    )
  }

  /**
   * 判断是否应该重试
   */
  shouldRetry(error) {
    const { config, response } = error

    // 已经重试过的请求不再重试
    if (config?.__retryCount >= API_CONFIG.retryAttempts) {
      return false
    }

    // 如果是取消请求，不进行重试
    if (axios.isCancel(error)) {
      return false
    }

    // 非幂等请求（POST/PUT/PATCH/DELETE）不自动重试，防止重复提交
    const idempotentMethods = ['get', 'head', 'options']
    if (!idempotentMethods.includes(config?.method?.toLowerCase())) {
      return false
    }

    // 413 Payload Too Large 和 431 Request Header Fields Too Large 绝不重试，避免网关雪崩
    if (response && (response.status === 413 || response.status === 431)) {
      return false
    }

    // 网络错误或服务器错误才重试
    const retryableStatuses = [408, 429, 500, 502, 503, 504]
    return !response || retryableStatuses.includes(response.status)
  }

  /**
   * 重试请求
   */
  async retryRequest(config) {
    config.__retryCount = (config.__retryCount || 0) + 1

    const delay = API_CONFIG.retryDelay * config.__retryCount

    await new Promise(resolve => setTimeout(resolve, delay))
    return this.client(config)
  }

  /**
   * GET 请求
   */
  async get(url, config = {}) {
    return this.client.get(url, config)
  }

  /**
   * POST 请求
   */
  async post(url, data = {}, config = {}) {
    return this.client.post(url, data, config)
  }

  /**
   * PUT 请求
   */
  async put(url, data = {}, config = {}) {
    return this.client.put(url, data, config)
  }

  /**
   * PATCH 请求
   */
  async patch(url, data = {}, config = {}) {
    return this.client.patch(url, data, config)
  }

  /**
   * DELETE 请求
   */
  async delete(url, config = {}) {
    return this.client.delete(url, config)
  }

  /**
   * 上传文件
   */
  async upload(url, file, onProgress = null) {
    const formData = new FormData()
    formData.append('file', file)

    return this.client.post(url, formData, {
      onUploadProgress: progressEvent => {
        if (onProgress) {
          const percentCompleted = Math.round((progressEvent.loaded * 100) / progressEvent.total)
          onProgress(percentCompleted)
        }
      }
    })
  }

  /**
   * 下载文件
   */
  async download(url, filename = null) {
    const response = await this.client.get(url, {
      responseType: 'blob'
    })

    // 创建下载链接
    const blob = new Blob([response.data])
    const downloadUrl = window.URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = downloadUrl
    link.download = filename || 'download'
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
    window.URL.revokeObjectURL(downloadUrl)

    return response
  }

  /**
   * 取消请求
   */
  createCancelToken() {
    return axios.CancelToken.source()
  }

  /**
   * 批量请求
   */
  async all(requests) {
    return Promise.all(requests)
  }

  /**
   * 健康检查
   */
  async healthCheck() {
    try {
      const response = await this.get('/health', {
        timeout: 5000,
        cache: false
      })
      return response.status === 200
    } catch (error) {
      console.warn('Health check failed:', error)
      return false
    }
  }

  /**
   * 获取应用列表 (已废弃 - 现在使用静态配置)
   * @deprecated 使用 angular-modules.config.ts 中的静态配置
   */
  async getApplets() {
    console.warn('⚠️ getApplets() is deprecated. Use static module configuration instead.')
    throw new Error(
      'getApplets() is deprecated. Use static module configuration from angular-modules.config.ts'
    )
  }

  /**
   * 获取系统统计信息
   */
  async getSystemStats() {
    // 直接返回模拟数据，避免404错误
    return this.getMockStats()
  }

  /**
   * 获取首页仪表盘全量数据
   */
  async getDashboardFullData() {
    const res = await this.get('/dashboard/api/sys/dashboard/full-data')
    const data = res?.data || {}

    // Adapt backend payload into frontend expected shape when necessary
    // - Ensure recentJobStats has totalJobs
    // - Map linuxVulnStats -> vulnerabilityOverview if frontend field missing
    const adapted = { ...data }
    if (Array.isArray(adapted.recentJobStats)) {
      adapted.recentJobStats = adapted.recentJobStats.map(i => ({
        ...i,
        totalJobs: (i?.restJobs || 0) + (i?.scriptJobs || 0) + (i?.commandJobs || 0)
      }))
    }
    if (!adapted.vulnerabilityOverview && adapted.linuxVulnStats) {
      adapted.vulnerabilityOverview = adapted.linuxVulnStats
    }

    return adapted
  }

  /**
   * 获取当前登录账户信息（使用 fullName 展示）
   */
  async getAccount() {
    const res = await this.get('/api/account', { cache: false })
    return res?.data
  }

  /**
   * 获取系统参数
   * @param {string} domain 参数域，如 'ai'
   * @param {string} name 参数名，如 'url'
   */
  async getParam(domain, name) {
    const safeDomain = encodeURIComponent(domain)
    const safeName = encodeURIComponent(name)
    const res = await this.get(`/api/params/${safeDomain}/${safeName}`, { cache: false })
    return res?.data
  }

  /**
   * 模拟统计数据
   */
  getMockStats() {
    return [
      {
        id: 'jobs',
        title: '作业总数',
        value: 156,
