// 创建全局实例
export const apiService = new ApiService()

const JAO_OPERATION_LOG_PATH = '/workflow/api/workflow/dashboard/list-operation-log'

function normalizeOperationLogStatus(status) {
  if (status === 'SUCCESS') {
    return 'COMPLETED'
  }
  return status
}

function normalizeOperationLogStatusFilter(status) {
  if (!status || status === 'all') {
    return 'all'
  }

  return String(status)
    .split(',')
    .map(item => item.trim())
    .filter(Boolean)
    .map(item => item)
    .join(',')
}

function normalizeOperationLogRecord(record = {}) {
  return {
    ...record,
    status: normalizeOperationLogStatus(record.status),
    target_hosts: record.target_hosts || ''
  }
}

function parseOperationLogFilter(filter) {
  if (!filter || typeof filter !== 'string') {
    return null
  }

  const [rawFields, rawKeyword = ''] = filter.split(':')
  const keyword = rawKeyword.replace(/^\*/, '').replace(/\*$/, '').trim().toLowerCase()
  const fields = (rawFields || '')
    .split('|')
    .map(item => item.trim())
    .filter(Boolean)

  if (!fields.length || !keyword) {
    return null
  }

  return { fields, keyword }
}

function applyOperationLogFilter(records, filter) {
  const parsed = parseOperationLogFilter(filter)
  if (!parsed) {
    return records
  }

  return records.filter(record =>
    parsed.fields.some(field => String(record?.[field] || '').toLowerCase().includes(parsed.keyword))
  )
}

export async function getJaoOperationLogs(params = {}, options = {}) {
  const queryParams = {
    module: params.module,
    action: params.action || 'all',
    status: normalizeOperationLogStatusFilter(params.status),
    day: params.day ?? 'all'
  }

  if (options.filter) {
    const response = await apiService.get(JAO_OPERATION_LOG_PATH, {
      params: queryParams
    })
    const payload = response?.data || {}
    const allRecords = Array.isArray(payload.data)
      ? payload.data.map(item => normalizeOperationLogRecord(item))
      : []
    const filteredRecords = applyOperationLogFilter(allRecords, options.filter)
    const page = Number(options.page) > 0 ? Number(options.page) : 1
    const size = Number(options.size) > 0 ? Number(options.size) : filteredRecords.length
    const startIndex = (page - 1) * size
    const pagedRecords = filteredRecords.slice(startIndex, startIndex + size)

    return {
      ...payload,
      data: pagedRecords,
      records: pagedRecords,
      total: filteredRecords.length
    }
  }

  if (Number(options.page) > 0) {
    queryParams.page = Number(options.page)
  }
  if (Number(options.size) > 0) {
    queryParams.size = Number(options.size)
  }

  const response = await apiService.get(JAO_OPERATION_LOG_PATH, {
    params: queryParams
  })
  const payload = response?.data || {}
  const records = Array.isArray(payload.data)
    ? payload.data.map(item => normalizeOperationLogRecord(item))
    : []

  return {
    ...payload,
    data: records,
    records,
    total: payload.total ?? records.length
  }
}

// 导出便捷方法
export const { get, post, put, patch, delete: del, upload, download } = apiService

// 导出 Composition API
export const useApi = () => {
  return {
    get: apiService.get.bind(apiService),
    post: apiService.post.bind(apiService),
    put: apiService.put.bind(apiService),
    patch: apiService.patch.bind(apiService),
    delete: apiService.delete.bind(apiService),
    upload: apiService.upload.bind(apiService),
    download: apiService.download.bind(apiService),
    createCancelToken: apiService.createCancelToken.bind(apiService),
    healthCheck: apiService.healthCheck.bind(apiService)
  }
}

/**
 * 资产管理模块 API
 */
import { apiService, getJaoOperationLogs } from '@/core/api'

// ACM API 基础路径
const ACM_BASE = '/cmdb/api/cmdb'
const ACM_DASHBOARD_BASE = `${ACM_BASE}/dashboard`
const SYS_DASHBOARD_BASE = '/dashboard/api/sys/dashboard'
const JAO_DASHBOARD_BASE = '/workflow/api/workflow/dashboard'


const unwrapApiData = (response) => {
  const body = response?.data
  if (body && body.data && Array.isArray(body.data) && body.total !== undefined) {
    return body
  }
  return body?.data ?? body
}

const normalizeRecords = (payload) => {
  if (!payload) return { records: [], total: 0 }
  if (Array.isArray(payload)) {
    return { records: payload, total: payload.length }
  }
  if (Array.isArray(payload.data)) {
    return {
      records: payload.data,
      total: payload.total ?? payload.data.length
    }
  }
  if (Array.isArray(payload.records)) {
    return {
      records: payload.records,
      total: payload.total ?? payload.records.length
    }
  }
  if (Array.isArray(payload.content)) {
    return {
      records: payload.content,
      total: payload.totalElements ?? payload.total ?? payload.content.length
    }
  }
  return { records: [], total: 0 }
}

const normalizeSingleItem = (payload) => {
  if (!payload) return null
  if (Array.isArray(payload)) return payload[0] || null
  if (Array.isArray(payload.records)) return payload.records[0] || null
  if (Array.isArray(payload.content)) return payload.content[0] || null
  return payload
}

const parseStringListValue = (value) => {
  if (Array.isArray(value)) return value.filter(Boolean)
  if (typeof value !== 'string' || !value.trim()) return []

  try {
    const parsed = JSON.parse(value)
    return Array.isArray(parsed) ? parsed.filter(Boolean) : []
  } catch {
    return []
  }
}

const normalizePagedRecords = (payload) => {
  if (!payload) {
    return {
      records: [],
      total: 0,
      content: [],
      totalElements: 0
    }
  }

  if (Array.isArray(payload)) {
    return {
      records: payload,
      total: payload.length,
      content: payload,
      totalElements: payload.length
    }
  }

  const records = Array.isArray(payload.records)
    ? payload.records
    : Array.isArray(payload.content)
      ? payload.content
      : []
  const total = payload.total ?? payload.totalElements ?? records.length

  return {
    ...payload,
    records,
    total,
    content: Array.isArray(payload.content) ? payload.content : records,
    totalElements: payload.totalElements ?? total
  }
}



/**
 * 资产总览 API
 */
export const overviewApi = {
  /**
   * 获取连接状态统计
   * GET /cmdb/api/cmdb/dashboard/connection-count
   */
  getConnectionCount() {
    return apiService.get(`${ACM_DASHBOARD_BASE}/connection-count`).then(res => normalizeRecords(unwrapApiData(res)))
  },

  /**
   * 获取资产类型统计
   * GET /cmdb/api/cmdb/dashboard/cit-manage
   */
  getAssetTypeCount() {
    return apiService.get(`${ACM_DASHBOARD_BASE}/cit-manage`).then(res => normalizeRecords(unwrapApiData(res)))
  },

  /**
   * 获取操作系统分布
   * GET /cmdb/api/cmdb/dashboard/os-distro
   */
  getOsDistribution() {
    return apiService.get(`${ACM_DASHBOARD_BASE}/os-distro`).then(res => normalizeRecords(unwrapApiData(res)))
  },

  /**
   * 获取资产新增统计
   * GET /cmdb/api/cmdb/dashboard/ci-new-count
   */
  getNewAssetCount() {
    return apiService.get(`${ACM_DASHBOARD_BASE}/ci-new-count`).then(res => normalizeRecords(unwrapApiData(res)))
  },

  /**
   * 获取分组内资产分布
   * GET /cmdb/api/cmdb/query/group/find/group/sum?os={os}
   * @param {string} os - 操作系统列表，逗号分隔
   */
  getGroupAssetCount(os = 'CentOS,Windows,Anolis,Debian,RedHat,Debian') {
    return apiService.get(`${ACM_BASE}/query/group/find/group/sum`, { params: { os } }).then(res => normalizeRecords(unwrapApiData(res)))
  },

  /**
   * 获取操作系统版本分布
   * GET /cmdb/api/cmdb/dashboard/os-version
   * @param {string} osDistro - 操作系统发行版
   */
  getOsVersionDistribution(osDistro) {
    return apiService
      .get(`${ACM_DASHBOARD_BASE}/os-version`, { params: { osDistro } })
      .then(res => normalizeRecords(unwrapApiData(res)))
  }
}

/**
 * 资产信息 API
 */
export const assetApi = {
  /**
   * 获取资产类型列表
